def _projection_limits(text: str) -> tuple[int, ...]:
    """Return only ordinary bounded rolling-window sizes.

    Complete structural blocks are separate exact-span candidates. Their lengths
    must not widen every unrelated window or subsequent snippet expansion.
    """
    limits = set(_BASE_WINDOW_LIMITS)
    compact_length = len(text.strip())
    if _BASE_WINDOW_LIMITS[-1] < compact_length <= _SHORT_COMPLETE_SOURCE_MAX_CHARS:
        limits.add(compact_length)
    return tuple(sorted(limits))

def _focused_line_range(
    text: str, start: int, end: int, source_line_start: Any,
) -> tuple[int | None, int | None]:
    if not isinstance(source_line_start, int) or source_line_start < 1:
        return None, None
    line_start = source_line_start + text[:start].count("\n")
    line_end = line_start + text[start:end].count("\n")
    return line_start, line_end

def _requalify_visible_source(
    source: dict[str, Any], *, query_text: dict[str, str],
) -> dict[str, Any]:
    visible_text = "\n".join(str(source.get(key) or "") for key in (
        "path_or_url", "section", "snippet",
    ))
    matches: dict[str, dict[str, Any]] = {}
    for query_id, trace in independent_query_probes(source, source.get("_independent_query_plan") or {}).items():
        if not isinstance(trace, dict) or trace.get("derived_from_query_id"):
            continue
        # A physically contiguous continuation of the same structured atom was
        # qualified by source structure upstream, not by lexical coincidence in
        # this child.  Preserve that derived canonical context while still
        # refusing to manufacture original/public coverage.
        if (
            query_id != "query-original"
            and trace.get("qualified") is True
            and trace.get("qualification_route") in {"same_atom_continuation", "same_list_item_continuation"}
            and trace.get("coverage_kind") == "derived"
        ):
            from .context_query_probes import revalidate_structural_continuation
            continuation_trace = revalidate_structural_continuation(trace, source, visible_text)
            matches = merge_query_matches(
                matches, {str(query_id): continuation_trace},
            )
            continue
        # Aggregated lineage belongs to the old window; rebuild it from visible probes.
        probe = {k: v for k, v in trace.items() if k not in {"coverage_kinds", "derived_from_query_ids"}}
        if query_id == "query-original":
            probe["exact_terms"] = list(dict.fromkeys((
                *(probe.get("exact_terms") or ()),
                *(term.normalized_value for term in documentation_exact_terms(
                    query_text.get(str(query_id), ""),
                )),
            )))
        if not probe.get("query_terms") and not probe.get("query_text"):
            planned_text = query_text.get(str(query_id), "")
            if planned_text:
                probe["query_text"] = planned_text
                probe["query_terms"] = sorted(_query_terms((planned_text,)))
        qualification = qualify_evidence(
            probe, query_id=str(query_id), visible_text=visible_text,
            evidence_text=str(source.get("snippet") or ""),
            catalog_role=str(source.get("catalog_role") or ""),
            candidate={**source.get("_qualification_candidate", {}), **source},
            expected_project_identity=source.get("_expected_project_identity"),
            lifecycle_intent=source.get("_lifecycle_intent", "current"),
        )
        qualified_trace = apply_retrieval_need_witness(
            {**probe, "query_id": query_id, "text": query_text.get(str(query_id), "")}, qualification.trace,
            str(source.get("snippet") or ""), source={"verified_owner": qualification.trace.get("bound_subject_context"), "authority": source.get("authority"), "lifecycle_status": "active"})
        matches = merge_query_matches(matches, {str(query_id): qualified_trace})
        parent_trace = derived_parent_trace(
            qualified_trace,
            source_query_id=str(query_id),
            parent_query_id=str(trace.get("public_parent_query_id") or ""),
        )
        if parent_trace is not None and query_id in query_text:
            matches = merge_query_matches(
                matches,
                {str(trace["public_parent_query_id"]): parent_trace},
            )
    qualified_ids = [
        query_id for query_id, trace in matches.items() if trace.get("qualified") is True
    ]
    return {
        **source,
        "retrieval_query_matches": matches,
        "retrieval_query_ids": qualified_ids,
    }

def qualified_query_ids(sources: Iterable[Mapping[str, Any]]) -> set[str]:
    qualified: set[str] = set()
    for source in sources:
        matches = source.get("retrieval_query_matches") or {}
        qualified.update(
            str(query_id)
            for query_id, trace in matches.items()
            if isinstance(trace, Mapping) and trace.get("qualified") is True
        )
    return qualified

def visible_assignments(
    original: Mapping[str, Any], projected: Mapping[str, Any],
    assignments: Iterable[Mapping[str, Any]],
) -> tuple[Mapping[str, Any], ...]:
    """Retain assignment identity after verifying its source-local occurrence.

    Equal hashes identify equal text, not interchangeable sources, offsets or
    requirements. Coverage must consume these verified assignments, not hashes.
    """
    if not isinstance(original, Mapping):
        return ()
    source_ids = {
        str(original.get(key) or "") for key in ("stable_id", "stable_chunk_id", "evidence_id")
        if original.get(key)
    }
    raw_text = next((value for value in (
        original.get("code"), original.get("snippet"), original.get("content"),
        original.get("display_text"),
    ) if isinstance(value, str) and value), "")
    visible_text = str(projected.get("snippet") or "")
    visible_span = source_local_span(
        raw_text, visible_text, source_line_start=original.get("line_start"),
        line_start=projected.get("line_start"), line_end=projected.get("line_end"),
    )
    if visible_span is None:
        return ()
    source_start = original.get("char_start")
    visible: list[Mapping[str, Any]] = []
    for assignment in assignments:
        if not isinstance(assignment, Mapping) or str(assignment.get("evidence_id") or "") not in source_ids:
            continue
        digest = str(assignment.get("projected_content_hash") or "")
        start, end = assignment.get("unit_char_start"), assignment.get("unit_char_end")
        if start is None and end is None:
            start, end = assignment.get("char_start"), assignment.get("char_end")
            if source_start is not None:
                if any(type(value) is not int for value in (source_start, start, end)):
                    continue
                start, end = start - source_start, end - source_start
        if digest and type(start) is int and type(end) is int and 0 <= start < end <= len(raw_text):
            witness = raw_text[start:end]
            if (visible_span[0] <= start < end <= visible_span[1]
                    and hashlib.sha256(witness.encode("utf-8")).hexdigest() == digest):
                visible.append(assignment)
    return tuple(visible)

def bind_visible_assignments(
    original: Mapping[str, Any], projected: Mapping[str, Any],
    assignments: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    """Bind a projected variant to exactly the canonical assignments it retains."""
    verified = visible_assignments(original, projected, assignments)
    return {
        **projected,
        "_visible_assignment_hashes": list(dict.fromkeys(
            str(item["projected_content_hash"]) for item in verified
        )),
        "_assigned_requirement_ids": list(dict.fromkeys(
            str(item["requirement_id"]) for item in verified if item.get("requirement_id")
        )),
    }

def context_selection_decision(
    sources: Iterable[Mapping[str, Any]], requested_query_ids: Iterable[str],
) -> ContextSelectionDecision:
    selected = tuple(str(source.get("evidence_id") or "") for source in sources)
    covered_set = attributable_query_ids(sources)
    requested = tuple(dict.fromkeys(str(value) for value in requested_query_ids if value))
    return ContextSelectionDecision(
        selected_evidence_ids=selected,
