class DocsFetchPolicy:
    """Validate every documentation URL before dispatching a request."""

    resolver: Resolver | None = None
    allowed_hosts: tuple[str, ...] = ()
    path_prefixes: tuple[str, ...] = ()
    allow_subdomains: bool = True

    def allows_scope(self, url: str) -> bool:
        try:
            parsed = urlparse(url)
            host = parsed.hostname
            parsed.port
        except (TypeError, ValueError):
            return False
        if (
            parsed.scheme not in {"http", "https"}
            or not host
            or parsed.username is not None
            or parsed.password is not None
        ):
            return False
        normalized_host = host.rstrip(".").lower()
        return bool(
            (not self.allowed_hosts or self._host_allowed(normalized_host))
            and (not self.path_prefixes or _path_allowed(parsed.path or "/", self.path_prefixes))
        )

    def validate_url(self, url: str) -> ValidatedDocsTarget:
        try:
            parsed = urlparse(url)
            host = parsed.hostname
            port = parsed.port
            username = parsed.username
            password = parsed.password
        except (TypeError, ValueError):
            raise DocsFetchSecurityError("invalid_url", "<invalid-url>") from None
        redacted = _redact_url(parsed)
        if parsed.scheme not in {"https", "http"}:
            raise DocsFetchSecurityError("unsupported_scheme", redacted)
        if username is not None or password is not None:
            raise DocsFetchSecurityError("userinfo_not_allowed", redacted)
        if not host:
            raise DocsFetchSecurityError("missing_host", redacted)
        normalized_host = host.rstrip(".").lower()
        if self.allowed_hosts and not self._host_allowed(normalized_host):
            raise DocsFetchSecurityError("host_not_allowed", redacted)
        if self.path_prefixes and not _path_allowed(parsed.path or "/", self.path_prefixes):
            raise DocsFetchSecurityError("path_not_allowed", redacted)
        try:
            literal_ip = ipaddress.ip_address(normalized_host)
        except ValueError:
            literal_ip = None
        try:
            answers = (
                (literal_ip,)
                if literal_ip is not None
                else tuple((self.resolver or resolve_host)(normalized_host))
            )
        except (OSError, UnicodeError, ValueError):
            raise DocsFetchSecurityError("dns_failure", redacted, phase="resolving", retryable=True) from None
        if not answers:
            raise DocsFetchSecurityError("dns_failure", redacted, phase="resolving", retryable=True)
        for answer in answers:
            if _is_blocked_ip(answer):
                raise DocsFetchSecurityError("private_network_blocked", redacted)
        return ValidatedDocsTarget(
            url=url,
            redacted_url=redacted,
            scheme=parsed.scheme,
            host=normalized_host,
            port=port or (443 if parsed.scheme == "https" else 80),
            resolved_ips=tuple(sorted({str(answer) for answer in answers})),
        )

    def _host_allowed(self, host: str) -> bool:
        if self.allow_subdomains:
            return _host_allowed(host, self.allowed_hosts)
        return host in {allowed.rstrip(".").lower() for allowed in self.allowed_hosts}

def assess_documentation_evidence(
    *,
    library: str,
    ecosystem: str | None,
    docs_url: str | None,
    authority: str | None,
    requested_version: str | None,
    version_binding: str | None,
    version_source: str | None = None,
    discovered_from: str | None = None,
) -> DocumentationEvidenceReport:
    """Return accept/confirm/reject without inventing a numeric confidence score."""

    identity_evidence: list[str] = []
    identity_conflicts: list[str] = []
    identity_missing: list[str] = []
    if library.strip() and ecosystem:
        identity_evidence.append(f"declared:{ecosystem}:{library}")
    else:
        identity_missing.append("package identity is incomplete")
    if discovered_from:
        identity_evidence.append(f"registry_metadata:{discovered_from}")
    parsed = urlparse(docs_url or "")
    if docs_url and (parsed.scheme != "https" or not parsed.hostname):
        identity_conflicts.append("documentation URL is not a safe HTTPS origin")

    authority_evidence = [authority] if authority else []
    authority_conflicts: list[str] = []
    authority_status = "confirmed" if authority in _OFFICIAL_AUTHORITIES else "unconfirmed"
    expected_hosts = _REGISTRY_HOSTS.get(str(ecosystem or "").casefold())
    if authority == "official_registry" and expected_hosts and parsed.hostname not in expected_hosts:
        authority_status = "rejected"
        authority_conflicts.append(
            f"official registry authority conflicts with origin {parsed.hostname or 'missing'}"
        )
    if not authority:
        authority_conflicts.append("source authority has not been established")

    version_evidence: list[str] = []
    version_conflicts: list[str] = []
    version_status = "unconfirmed"
    if version_binding in {"rolling", "channel"}:
        version_status = "confirmed"
        version_evidence.append(f"binding:{version_binding}")
    elif version_binding == "exact":
        if version_source in _EXACT_SOURCES:
            version_status = "confirmed"
            version_evidence.append(f"resolved:{version_source}")
        elif requested_version and requested_version in (docs_url or ""):
            version_status = "confirmed"
            version_evidence.append("version appears in documentation URL")
        else:
            version_conflicts.append("exact version binding lacks resolution evidence")
    else:
        version_conflicts.append("documentation version binding is unconfirmed")

    identity_status = (
        "rejected" if identity_conflicts else
        ("unconfirmed" if identity_missing else "confirmed")
    )
    if identity_status == "rejected" or authority_status == "rejected":
        decision = "reject"
    elif authority_status == "confirmed" and version_status == "confirmed":
        decision = "accept"
    else:
        decision = "confirm"
    reasons = [*identity_conflicts, *identity_missing, *authority_conflicts, *version_conflicts]
    return DocumentationEvidenceReport(
        decision=decision,
        identity=EvidenceDimension(identity_status, identity_evidence, [*identity_conflicts, *identity_missing]),
        authority=EvidenceDimension(authority_status, authority_evidence, authority_conflicts),
        version=EvidenceDimension(version_status, version_evidence, version_conflicts),
        reasons=reasons,
    )

def _inspection_path_prefixes(urls: list[str]) -> tuple[str, ...]:
    prefixes: list[str] = []
    for url in urls:
        path = urlparse(url).path or "/"
        parent = str(PurePosixPath(path).parent)
        prefix = path if path.endswith("/") else (parent.rstrip("/") + "/" or "/")
        if prefix not in prefixes:
            prefixes.append(prefix)
    return tuple(prefixes)

class DocsHttpClient:
    """Validate DNS and every redirect target before forwarding GET requests."""

    def __init__(
        self,
        client,
        policy: DocsFetchPolicy,
        *,
        max_redirects: int = 5,
        max_response_bytes: int = 8 * 1024 * 1024,
        max_decoded_text_bytes: int = 16 * 1024 * 1024,
        clock: Callable[[], float] = monotonic,
        max_total_seconds: float | None = None,
        deadline_at: float | None = None,
        transfer_counter: Callable[[httpx.Response], int] | None = None,
        pin_resolved_ips: bool = True,
    ) -> None:
        self._client = client
        self._policy = policy
        self._max_redirects = max_redirects
        self._max_response_bytes = max_response_bytes
        self._max_decoded_text_bytes = max_decoded_text_bytes
        self._clock = clock
        self._max_total_seconds = max_total_seconds
        self._deadline_at = deadline_at
        self._transfer_counter = transfer_counter or (lambda response: response.num_bytes_downloaded)
        self._pin_resolved_ips = pin_resolved_ips

    def __enter__(self):
        return self

    def __exit__(self, exc_type=None, exc=None, traceback=None) -> None:
        self.close()

    def get(self, url: httpx.URL | str, **kwargs) -> httpx.Response:
        current = str(url)
        started_at = self._clock()
        for redirects in range(self._max_redirects + 1):
            deadline = self._deadline_at
            if deadline is None and self._max_total_seconds is not None:
                deadline = started_at + self._max_total_seconds
            if deadline is not None and self._clock() >= deadline:
                raise DocsFetchSecurityError("request_timeout", redact_url(current))
            first = self._policy.validate_url(current)
            second = self._policy.validate_url(current)
            self._validate_stable_resolution(first, second)
            request_kwargs = dict(kwargs)
            if deadline is not None:
                request_kwargs.setdefault("timeout", max(0.001, deadline - self._clock()))
            try:
                response = self._request_once(current, first, **request_kwargs)
            except httpx.RequestError as exc:
                raise DocsFetchSecurityError(
                    _network_failure_category(exc),
                    first.redacted_url,
                    phase="fetching",
                    retryable=True,
                ) from None
            try:
                reported_url = response.url
            except (AttributeError, RuntimeError):
                reported_url = None
            if isinstance(reported_url, httpx.URL):
                self._policy.validate_url(str(reported_url))
            if response.status_code not in _REDIRECT_STATUSES:
                if not isinstance(self._client, _HTTPX_CLIENT_TYPE):
                    self._validate_response(response, first)
                return response
            location = getattr(response, "headers", {}).get("location")
            if not location:
                self._validate_response(response, first)
                return response
            if redirects == self._max_redirects:
                raise DocsFetchSecurityError("too_many_redirects", first.redacted_url)
            current = urljoin(current, location)
        raise DocsFetchSecurityError("too_many_redirects", current)

    def _request_once(self, url: str, target: ValidatedDocsTarget, **kwargs) -> httpx.Response:
        if not isinstance(self._client, _HTTPX_CLIENT_TYPE):
            return self._client.get(url, **kwargs)
        last_connect_error: httpx.RequestError | None = None
        addresses = target.resolved_ips if self._pin_resolved_ips else (target.host,)
        for address in addresses:
            try:
                return self._request_pinned(url, target, address, **kwargs)
            except (httpx.ConnectError, httpx.ConnectTimeout) as exc:
                last_connect_error = exc
        assert last_connect_error is not None
        raise last_connect_error

    def _request_pinned(
        self,
        url: str,
        target: ValidatedDocsTarget,
        address: str,
        **kwargs,
    ) -> httpx.Response:
        pinned_url = _pinned_url(url, address)
        headers = dict(kwargs.pop("headers", {}) or {})
        default_port = 443 if target.scheme == "https" else 80
        headers["Host"] = target.host if target.port == default_port else f"{target.host}:{target.port}"
        extensions = dict(kwargs.pop("extensions", {}) or {})
        extensions["sni_hostname"] = target.host
        original_request = httpx.Request("GET", url)
        with self._client.stream(
            "GET",
            pinned_url,
            headers=headers,
            extensions=extensions,
            follow_redirects=False,
            **kwargs,
        ) as response:
            self._validate_headers(response, target)
            if response.status_code in _REDIRECT_STATUSES:
                return httpx.Response(
                    response.status_code,
                    headers=response.headers,
                    request=original_request,
                )
            chunks: list[bytes] = []
            decoded_size = 0
            for chunk in response.iter_bytes():
                decoded_size += len(chunk)
                if (
                    decoded_size > self._max_decoded_text_bytes
                    or self._transfer_counter(response) > self._max_response_bytes
                ):
                    raise DocsFetchSecurityError("response_too_large", target.redacted_url)
                chunks.append(chunk)
            response_headers = response.headers.copy()
            response_headers.pop("content-encoding", None)
            response_headers.pop("content-length", None)
            return httpx.Response(
                response.status_code,
                headers=response_headers,
                content=b"".join(chunks),
                request=original_request,
            )

    @staticmethod
    def _validate_stable_resolution(first: ValidatedDocsTarget, second: ValidatedDocsTarget) -> None:
        if first.resolved_ips != second.resolved_ips:
            raise DocsFetchSecurityError("dns_resolution_changed", first.redacted_url)

    def _validate_response(self, response, target: ValidatedDocsTarget) -> None:
        self._validate_headers(response, target)
        content = getattr(response, "content", None)
        if isinstance(content, bytes) and len(content) > self._max_response_bytes:
            raise DocsFetchSecurityError("response_too_large", target.redacted_url)

    def _validate_headers(self, response, target: ValidatedDocsTarget) -> None:
        headers = getattr(response, "headers", {})
        raw_length = headers.get("content-length")
        if raw_length:
            try:
                content_length = int(raw_length)
            except (TypeError, ValueError):
                raise DocsFetchSecurityError("invalid_content_length", target.redacted_url) from None
            if content_length > self._max_response_bytes:
                raise DocsFetchSecurityError("response_too_large", target.redacted_url)
        if getattr(response, "status_code", None) in _REDIRECT_STATUSES:
            return
        content_type = headers.get("content-type", "").split(";", 1)[0].strip().lower()
        if not any(
            content_type == allowed or content_type.startswith(allowed)
            for allowed in _ALLOWED_CONTENT_TYPES
        ):
            raise DocsFetchSecurityError("content_type_blocked", target.redacted_url)

    def close(self) -> None:
        close = getattr(self._client, "close", None)
        if close:
            close()

def redact_url(url: str) -> str:
    """Return a URL safe for public errors, progress events, and logs."""
    try:
        return _redact_url(urlparse(url))
    except (TypeError, ValueError):
        return "<invalid-url>"

