def _verified_document(original: dict, public: dict) -> str | None:
    ref = original.get('_reference_evidence')
    if not isinstance(ref, dict):
        return None
    raw = ref.get('raw_document')
    identity = ref.get('source') or {}
    if not isinstance(raw, str) or not raw or len(raw) > MAX_SNAPSHOT_CHARS:
        return None
    if hashlib.sha256(raw.encode('utf-8')).hexdigest() != identity.get('content_sha256'):
        return None
    if public.get('project_identity') != original.get('project_identity'):
        return None
    if public.get('path_or_url') != identity.get('canonical_path'):
        return None
    _, reason = prepare_reference_probe({}, candidate=original, evidence_text=public['snippet'])
    if reason is not None:
        return None
    return raw

def structural_spans(raw: str, start: int, end: int) -> tuple[tuple[int, int, str], ...]:
    """Coalesce lazy list continuations without changing index chunking.

    A continuation directly after a list marker belongs to that item. A prose
    paragraph after a blank line terminates it. Consecutive items stay one run.
    """
    out: list[tuple[int, int, str]] = []
    for atom in _atom_spans(raw, start, end):
        if out and out[-1][2] == "list":
            a, b, kind = out[-1]
            joined = atom.atom_type == "list" or (
                atom.atom_type == "prose" and not raw[a:b].endswith(("\n\n", "\r\n\r\n"))
            )
            if joined:
                out[-1] = (a, atom.end, kind)
                continue
        out.append((atom.start, atom.end, atom.atom_type))
    return tuple(out)

def _atom_spans(content: str, start: int, end: int) -> list[_AtomSpan]:
    """Split a parent at Markdown block boundaries without changing text."""
    relative = content[start:end]
    lines, offsets = _line_offsets(relative)
    spans: list[_AtomSpan] = []
    i = 0
    while i < len(lines):
        block_start = i
        fence = _FENCE.match(lines[i])
        if fence:
            atom_type = "code"
            marker = fence.group(1)
            i += 1
            while i < len(lines):
                closing = _FENCE.match(lines[i])
                i += 1
                if closing and closing.group(1)[0] == marker[0] and len(closing.group(1)) >= len(marker):
                    break
        elif lines[i].lstrip().startswith("|"):
            atom_type = "table"
            i += 1
            while i < len(lines) and lines[i].lstrip().startswith("|"):
                i += 1
        elif _LIST.match(lines[i]):
            atom_type = "list"
            i += 1
            while i < len(lines) and (_LIST.match(lines[i]) or lines[i].startswith((" ", "\t"))):
                i += 1
        elif not lines[i].strip():
            atom_type = "whitespace"
            i += 1
        else:
            atom_type = "heading" if _HEADING.match(lines[i]) else "prose"
            i += 1
            while i < len(lines) and lines[i].strip() and not _FENCE.match(lines[i]) and not _LIST.match(lines[i]) and not lines[i].lstrip().startswith("|"):
                i += 1
        while i < len(lines) and not lines[i].strip():
            i += 1
        atom_start = start + offsets[block_start]
        atom_end = start + offsets[i]
        if atom_end > atom_start:
            # A colon-terminated introduction gives the immediately following
            # list its subject/relation. Keep that exact contiguous unit intact
            # before packing; oversized units still use the hard-limit splitter.
            if (atom_type == "list" and spans and spans[-1].atom_type == "prose"
                    and content[spans[-1].start:spans[-1].end].rstrip().endswith(":")):
                spans[-1] = _AtomSpan(spans[-1].start, atom_end, "list")
            else:
                spans.append(_AtomSpan(atom_start, atom_end, atom_type))
    return spans

