def seed_envelopes(payload: dict, snapshot: dict) -> list[tuple[int, tuple]]:
    groups: dict[tuple, list] = {}
    for index, row in enumerate(payload.get("sources", [])):
        source = (snapshot.get(row.get("evidence_id")) or {}).get("source")
        if not isinstance(source, dict):
            continue
        raw = _verified_document(source, row)
        if raw is None:
            continue
        ref = source["_reference_evidence"]
        start = raw.find(row["snippet"], ref["char_start"], ref["char_end"])
        end = start + len(row["snippet"])
        parents = parse_markdown_parents(raw, ref["source"]["document_id"])
        if len(parents) > MAX_PARENT_SECTIONS:
            continue
        owner = next((p for p in parents if p.char_start <= start < end <= p.char_end), None)
        if owner is None:
            continue
        key = (row["project_identity"], row["path_or_url"], source.get("_source_snapshot_sha256"),
               source.get("_source_catalog_hash"), source.get("resolved_version"), owner.logical_id)
        groups.setdefault(key, []).append((index, row, source, raw, owner, start, end))
    result = []
    for rows in groups.values():
        if len(rows) < 2:
            continue
        index, row, source, raw, owner, _, _ = rows[0]
        if any(item[3] != raw for item in rows):
            continue
        atoms = [a for a in structural_spans(raw, owner.char_start, owner.char_end) if a[2] != "whitespace"]
        left, right = min(item[5] for item in rows), max(item[6] for item in rows)
        hits = [i for i, (a, z, _) in enumerate(atoms) if a < right and left < z]
        if not hits:
            continue
        start, end = min(left, atoms[hits[0]][0]), max(right, atoms[hits[-1]][1])
        bounds = [(start, end)]
        if hits[0] > 0 and atoms[hits[0] - 1][2] == "prose":
            bounds.append((atoms[hits[0] - 1][0], end))
        seen = {row["snippet"]}
        for a, z in bounds:
            proposal = _context_row(source, row, raw, owner, a, z, supplementary=False)
            if proposal is not None and proposal[0]["snippet"] not in seen:
                seen.add(proposal[0]["snippet"])
                result.append((index, (*proposal, "seed_envelope")))
    return result

def source_options(public: dict, original: dict) -> tuple[list[tuple[dict, dict, str]], tuple[dict, dict] | None]:
    """Original plus at most two containing alternatives and one document intro."""
    options = [(deepcopy(public), deepcopy(original), "original")]
    raw = _verified_document(original, public)
    if raw is None:
        return options, None
    ref = original["_reference_evidence"]
    parents = parse_markdown_parents(raw, ref["source"]["document_id"])
    if not parents or len(parents) > MAX_PARENT_SECTIONS:
        return options, None
    start = raw.find(public["snippet"], ref["char_start"], ref["char_end"])
    end = start + len(public["snippet"])
    owner = next((p for p in parents if p.char_start <= start < end <= p.char_end), None)
    if owner is None:
        return options, None
    spans = structural_spans(raw, owner.char_start, owner.char_end)
    hits = [(a, b) for a, b, kind in spans if a < end and start < b and kind != "whitespace"]
    bounds = []
    if hits:
        bounds.append((min(start, hits[0][0]), max(end, hits[-1][1]), "complete_atom"))
    bounds.append((owner.char_start, owner.char_end, "containing_section"))
    seen = {public["snippet"]}
    for a, b, kind in bounds:
        proposal = _context_row(original, public, raw, owner, a, b, supplementary=False)
        if proposal is not None and proposal[0]["snippet"] not in seen:
            seen.add(proposal[0]["snippet"])
            options.append((*proposal, kind))
    intro = None
    first = parents[0]
    is_root = (first.level == 1 and len(owner.heading_path) > len(first.heading_path)
        and owner.heading_path[:len(first.heading_path)] == first.heading_path)
    if first.char_start == 0 and first.logical_id != owner.logical_id and is_root:
        body = next((a for a in _atom_spans(raw, first.char_start, first.char_end)
            if a.atom_type not in {"heading", "whitespace"} and raw[a.start:a.end].strip()), None)
        if body is not None and body.atom_type == "prose":
            intro = _context_row(original, public, raw, first, body.start, body.end, supplementary=True)
    return options, intro

def _draft_subsets(payload: dict, snapshot: dict, trial: dict, bindings: dict, retrieval: dict):
    """Coalesce only draft citations with full canonical lineage and no facet IDs."""
    yield trial, bindings
    if payload.get("facets") or len(trial["sources"]) < 2:
        return
    from .docs_context_projection import _requalify_visible_source
    plan = retrieval.get("documentation_query_plan") or {}
    texts = {str(q.get("query_id") or ""): str(q.get("text") or "")
             for q in plan.get("queries") or () if isinstance(q, dict)}
    for n in range(1, len(trial["sources"])):
        for rows in combinations(trial["sources"], n):
            p = deepcopy(trial)
            p["sources"] = list(deepcopy(rows))
            mapping = retained_seed_mapping(payload, snapshot, p, bindings)
            if not mapping:
                continue
            b = deepcopy(bindings)
            qualified_rows = []
            policy_rejected = False
            for row in p["sources"]:
                original = b[row["evidence_id"]]["source"]
                # Re-run the existing qualifier for the probes attached to
                # every retained occurrence. Never copy its old qualified flag.
                inherited = [original]
                inherited.extend(snapshot[eid]["source"] for eid, covering in mapping.items()
                                 if covering == row["evidence_id"] and eid != row["evidence_id"])
                checked = []
                for origin in inherited:
                    if any(evidence_policy_rejection_reason(
                        probe, visible_text=row["snippet"],
                        catalog_role=str(original.get("catalog_role") or ""), candidate=original,
                        expected_project_identity=row["project_identity"],
                        lifecycle_intent=original.get("_lifecycle_intent", "current"),
                    ) for probe in (origin.get("retrieval_query_matches") or {}).values() if isinstance(probe, dict)):
                        policy_rejected = True
                        break
                    visible = _requalify_visible_source({
                        **original, **row, "_qualification_candidate": original,
                        "_expected_project_identity": row["project_identity"],
                        "retrieval_query_matches": origin.get("retrieval_query_matches") or {},
                    }, query_text=texts)
                    checked.append(visible["retrieval_query_matches"])
                if policy_rejected:
                    break
                matches = merge_query_matches(*checked)
                original = {**original, "retrieval_query_matches": matches,
                    "retrieval_query_ids": [key for key, value in matches.items() if value.get("qualified") is True]}
                visible = {**visible, "retrieval_query_matches": matches,
                           "retrieval_query_ids": original["retrieval_query_ids"]}
                b[row["evidence_id"]] = _snapshot_entry(original, row)
                qualified_rows.append(visible)
            if policy_rejected or not set(payload.get("covered_query_ids") or ()) <= attributable_query_ids(qualified_rows):
                continue
            yield p, b

def _snapshot_entry(
    original: dict[str, Any], projected: dict[str, Any]
) -> dict[str, Any]:
    """Bind both raw source content and the exact model-visible source row."""

    canonical = dict(projected)
    # Keep the flat fields for the frozen Task 43 evaluator. New validation is
    # deliberately bound to projected_source so deleting or injecting a field
    # cannot exploit the evaluator's backwards-compatible snapshot shape.
    return {
        "source": deepcopy(original),
        "projected_source": canonical,
        **canonical,
    }

def _finish(payload: dict, snapshot: dict, retrieval: dict, root: str, budget: int):
    # Ordinary quality/capability primitives on private clones. The real handler
    # registers only the winning DTO, not these candidate drafts.
    from .docs_context_projection import _finalize_quality, _strip_legacy_locators
    p, b, r = deepcopy(payload), deepcopy(snapshot), deepcopy(retrieval)
    p["read_next"] = []
    b.pop("__read_next__", None)
    _strip_legacy_locators(p, b)
    _finalize_quality(r, p, b)
    if docs_context_budget_tokens(p) > budget:
        from .context_packet_labels import compact_section_labels
        p, b = compact_section_labels(p, b)
    if root:
        previous = payload.get("read_next") or []
        if previous:
            target = deepcopy(previous[0])
            source = (snapshot.get("__read_next__") or {}).get("source")
            if not isinstance(source, dict):
                return None
        else:
            target, source = prepare_docs_context_read_next(p, b, r, root=root)
        if target is not None and source is not None:
            visible = [(row["line_start"], row["line_end"]) for row in p["sources"]
                if row["path_or_url"] == target["path"]
                and row["project_identity"] == target["project_identity"]
                and (b[row["evidence_id"]]["source"].get("_source_snapshot_sha256") == target["snapshot_sha256"])]
            remaining = unread_lines(target["line_start"], target["line_end"], visible)
            if remaining:
                a, z = remaining[0]
                target = _read_next_row(root, source, line_start=a, line_end=z, reason=target["reason"])
            else:
                target = None
            if target is not None:
                if attach_docs_context_read_next(p, target, max_tokens=budget):
                    b["__read_next__"] = {"source": deepcopy(source)}
                elif previous:
                    # Unread obligations are not deleted to make a trial fit.
                    return None
        attach_source_continuation_locators(p, b, root=root, max_tokens=budget)
    _refresh_estimate(p)
    return p, b, r

def retained_seed_mapping(previous: dict, previous_snapshot: dict,
                          trial: dict, trial_snapshot: dict) -> dict[str, str]:
    """Map every old occurrence to its validated containing draft citation.

    Empty means failure, not partial success. Policy and query coverage must be
    independently checked by the caller after these canonical bounds match.
    """
    candidates = [(row, _occurrence(row, trial_snapshot)) for row in trial.get("sources") or ()]
    mapping: dict[str, str] = {}
    for old in previous.get("sources") or ():
        occurrence = _occurrence(old, previous_snapshot)
        if occurrence is None:
            return {}
        identity, a, b = occurrence
        containing = [row for row, current in candidates if current is not None
                      and current[0] == identity and current[1] <= a < b <= current[2]]
        if not containing:
            return {}
        same = next((row for row in containing if row["evidence_id"] == old["evidence_id"]), containing[0])
        mapping[old["evidence_id"]] = same["evidence_id"]
    return mapping

def validate_model_visible_projection(
    payload: Any, *, snapshot: dict[str, dict[str, Any]], max_tokens: int,
    canonical_selection: SelectionDecision | AggregateMixedSelectionDecision | None = None,
) -> list[str]:
    errors: list[str] = []
    if not isinstance(payload, dict):
        return ["model-visible projection must be an object"]
    forbidden = sorted(_find_forbidden_keys(payload))
    if forbidden:
        errors.append("forbidden model-visible keys: " + ", ".join(forbidden))
    status, kind = payload.get("status"), payload.get("kind")
    if kind not in {"docs_answer", "docs_context", "patch_context"}:
        errors.append("invalid projection kind")
    if status not in {"ok", "truncated", "insufficient_evidence"}:
        errors.append("invalid projection status")
    limit = (
        min(INSUFFICIENT_EVIDENCE_MAX_TOKENS, max_tokens)
        if status == "insufficient_evidence"
        else max_tokens
    )
    actual = estimate_projection_tokens(payload)
    if payload.get("estimated_tokens") != actual or actual > limit:
        errors.append("projection estimate mismatch or budget exceeded")
    if (
        kind == "docs_context"
        and status in {"ok", "truncated"}
        and docs_context_budget_tokens(payload) > max_tokens
    ):
        errors.append("docs_context conservative budget exceeded")
    if status == "insufficient_evidence":
        transport = payload.get("support_envelope")
        transport_support: dict[str, Any] | None = None
        if transport is not None:
            try:
                transport_support = decode_support_envelope(transport)
            except ValueError as exc:
                errors.append(str(exc))
        for key, expected in (
            ("answer_supported", False),
            ("answer_available", False),
            ("support_status", "insufficient_evidence"),
        ):
            if key in payload and payload[key] != expected:
                errors.append(f"insufficient evidence has inconsistent {key}")
        if transport_support is not None:
            for key in _INSUFFICIENT_SUPPORT_KEYS:
                if key in payload and key in transport_support and payload[key] != transport_support[key]:
                    errors.append(f"support envelope {key} does not match the model summary")
        if payload.get("implementation_guidance") or payload.get("invariants") or payload.get("targets"):
            errors.append("insufficient evidence must not authorize edits")
        decision = (
            canonical_selection.selection_decision
            if isinstance(canonical_selection, AggregateMixedSelectionDecision)
            else canonical_selection
        )
        if decision is not None:
            visible_hash = payload.get("decision_hash")
            envelope_hash = (
                transport_support.get("decision_hash")
                if transport_support is not None else None
            )
            if visible_hash not in {None, decision.support_decision.decision_hash}:
                errors.append("projection decision hash does not match canonical selection")
            if envelope_hash not in {None, decision.support_decision.decision_hash}:
                errors.append("support envelope decision hash does not match canonical selection")
        return errors
    sources = payload.get("sources")
    if not isinstance(sources, list) or not sources:
        errors.append("successful projections require sources")
        return errors
    if kind in {"docs_answer", "docs_context"} and len(sources) > MAX_DOCS_SOURCES:
        errors.append(f"{kind} exceeds source limit")
    ids: set[str] = set()
    allowed_fields = (
        DOCS_SOURCE_FIELDS if kind == "docs_answer" else
        DOCS_CONTEXT_SOURCE_FIELDS if kind == "docs_context" else
        PATCH_SOURCE_FIELDS
    )
    for source in sources:
        if not isinstance(source, dict):
            errors.append("projection source must be an object")
            continue
        evidence_id = str(source.get("evidence_id") or "")
        bound = snapshot.get(evidence_id)
        if not evidence_id or not bound:
            errors.append("projection evidence_id does not resolve to the internal snapshot")
            continue
        expected = bound.get("projected_source")
        if not isinstance(expected, dict):
            errors.append("internal snapshot is missing its canonical projected source")
            continue
        optional = {"source_uri"} if kind == "docs_context" else set()
        missing = sorted(allowed_fields - set(source))
        unknown = sorted(set(source) - allowed_fields - optional)
        for key in missing:
            errors.append(f"projection source field is missing: {key}")
        if unknown:
            errors.append(
                "projection source contains unknown fields: " + ", ".join(unknown)
            )
        if set(expected) - optional != allowed_fields:
            errors.append("internal snapshot projected source schema is invalid")
        if (set(source) & optional != set(expected) & optional
            or source.get("source_uri") != expected.get("source_uri")):
            errors.append("projection source locator does not match the internal snapshot")
        if source.get("content_sha256") != expected.get("content_sha256"):
            errors.append("projection source hash does not match the internal snapshot")
        bound_source = bound.get("source")
        if (
            not isinstance(bound_source, dict)
            or _source_digest(bound_source) != expected.get("content_sha256")
        ):
            errors.append("internal snapshot hash does not match its source content")
        for key in sorted(allowed_fields & set(source) & set(expected)):
            if source.get(key) != expected.get(key):
                errors.append(f"projection source {key} does not match the internal snapshot")
        ids.add(evidence_id)
    if kind == "docs_answer":
        answer_refs = payload.get("answer_evidence_ids")
        if not isinstance(answer_refs, list) or not answer_refs or any(ref not in ids for ref in answer_refs):
            errors.append("docs_answer claims require valid evidence IDs")
        decision = (
            canonical_selection.selection_decision
            if isinstance(canonical_selection, AggregateMixedSelectionDecision)
            else canonical_selection
        )
        if decision is not None:
            if payload.get("answer_supported") is not True:
                errors.append("successful docs answer must be supported")
            assigned_witnesses = {
                assignment.evidence_id for assignment in decision.assignments
            }
            if ids != assigned_witnesses or set(answer_refs or ()) != assigned_witnesses:
                errors.append("model-visible evidence does not match aggregate assigned witnesses")
            visible_sources = {
                str(source.get("evidence_id") or ""): source
                for source in sources if isinstance(source, dict)
            }
            candidates_by_id = {
                candidate.stable_id: candidate
                for candidate in decision.selected_candidates
            }
            requirements_by_id = {
                requirement.requirement_id: requirement
                for requirement in decision.requirements
            }
            for assignment in decision.assignments:
                candidate = candidates_by_id.get(assignment.evidence_id)
                requirement = requirements_by_id.get(assignment.requirement_id)
                visible = visible_sources.get(assignment.evidence_id)
                if candidate is None or requirement is None or visible is None:
                    errors.append("model-visible assignment does not resolve to canonical evidence")
                    continue
                if not validate_assignment_binding(requirement, candidate, assignment):
                    errors.append("model-visible assignment failed unit proof revalidation")
                    continue
                unit = resolve_assignment_unit(candidate, assignment)
                if unit is not None and unit.text not in str(visible.get("snippet") or ""):
                    errors.append("model-visible assignment unit is absent from its cited source")
    if kind == "docs_context":
        if payload.get("answer_policy") != "cite_only":
            errors.append("docs_context answer policy must be cite_only")
        if payload.get("answer_supported") is not False or payload.get("answer_available") is not False:
            errors.append("docs_context must not claim a supported answer")
        if payload.get("edit_ready") is not False:
            errors.append("docs_context must not authorize edits")
        if payload.get("implementation_guidance") or payload.get("invariants") or payload.get("targets"):
            errors.append("docs_context must not contain edit guidance")
        if any(not str(source.get("project_identity") or "").strip() for source in sources):
            errors.append("docs_context sources require project identity")
        errors.extend(validate_context_selection_payload(payload, sources, snapshot=snapshot))
    if kind == "patch_context":
