def estimate_projection_tokens(value: Any) -> int:
    size = len(canonical_projection_bytes(value))
    return max(1, math.ceil(size / 4))

def _find_forbidden_keys(value: Any) -> set[str]:
    found: set[str] = set()
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key) in FORBIDDEN_MODEL_KEYS:
                found.add(str(key))
            found.update(_find_forbidden_keys(child))
    elif isinstance(value, list):
        for child in value:
            found.update(_find_forbidden_keys(child))
    return found

def docs_context_budget_tokens(value: Any) -> int:
    """Admit only DTOs fitting both the public estimate and pinned offline codec."""
    from .projection_tokenizer import projection_token_count

    return max(estimate_projection_tokens(value), projection_token_count(canonical_projection_bytes(value)))

def validate_context_selection_payload(
    payload: Mapping[str, Any], sources: Iterable[Mapping[str, Any]],
    *, snapshot: Mapping[str, Mapping[str, Any]] | None = None,
) -> list[str]:
    coverage = payload.get("query_coverage")
    covered = payload.get("covered_query_ids")
    missing = payload.get("missing_query_ids")
    missing_facets = payload.get("missing_facets")
    facets = payload.get("facets")
    if (
        coverage not in {"full", "partial"}
        or not isinstance(covered, list)
        or not isinstance(missing, list)
        or set(covered).intersection(missing)
        or (coverage == "full") != bool(covered and not missing)
        or not isinstance(missing_facets, list)
        or not isinstance(facets, list)
        or any(
            item.get("status") not in {"covered", "missing", "retrieval_only"}
            or not str(item.get("id") or "").strip()
            or not str(item.get("question") or "").strip()
            or not isinstance(item.get("evidence_ids"), list)
            for item in facets if isinstance(item, Mapping)
        )
        or any(not isinstance(item, Mapping) for item in facets)
        or [item for item in facets if item.get("status") == "missing"] != missing_facets
        or payload.get("coverage_policy") != "retrieval_attribution_only"
        or payload.get("retrieval_coverage") != coverage
        or payload.get("facet_coverage") not in {"none", "partial", "full", "unverified"}
    ):
        return ["docs_context query coverage is inconsistent"]
    evidence_ids = {
        str(source.get("evidence_id") or "") for source in sources
        if str(source.get("evidence_id") or "")
    }
    if any(
        not set(str(value) for value in item.get("evidence_ids") or ()).issubset(evidence_ids)
        for item in facets if isinstance(item, Mapping)
    ):
        return ["docs_context facet evidence requires a visible source"]
    if snapshot is not None:
        for item in facets:
            if not isinstance(item, Mapping) or item.get("status") != "covered":
                continue
            requirement_id = str(item.get("requirement_id") or "")
            if not requirement_id or any(
                requirement_id not in set(
                    ((snapshot.get(str(evidence_id)) or {}).get("source") or {}).get(
                        "_assigned_requirement_ids"
                    ) or ()
                )
                for evidence_id in item.get("evidence_ids") or ()
            ):
                return ["docs_context covered facet requires its canonical assigned witness"]
    return []

def decode_support_envelope(value: Any) -> dict[str, Any]:
    """Decode the deterministic bounded transport, rejecting malformed input."""

    if not isinstance(value, dict) or value.get("encoding") != SUPPORT_ENVELOPE_ENCODING:
        raise ValueError("unsupported support envelope encoding")
    encoded = value.get("data")
    if not isinstance(encoded, str) or not encoded or len(encoded) > 8_192:
        raise ValueError("invalid support envelope data")
    padded = encoded + "=" * (-len(encoded) % 4)
    try:
        raw = zlib.decompress(base64.b64decode(padded, altchars=b"-_", validate=True))
        decoded = json.loads(raw)
    except (ValueError, TypeError, zlib.error, json.JSONDecodeError) as exc:
        raise ValueError("invalid support envelope data") from exc
    if len(raw) > 32_000 or not isinstance(decoded, dict):
        raise ValueError("invalid support envelope payload")
    if set(decoded) != set(SUPPORT_ENVELOPE_KEYS):
        raise ValueError("incomplete support envelope payload")
    return decoded

def _source_digest(item: dict[str, Any]) -> str:
    material = {
        "path": item.get("path") or item.get("source") or item.get("url") or item.get("source_url"),
        "section": item.get("heading_path") or item.get("title"),
        "content": item.get("content") or item.get("display_text"),
        "snippet": item.get("snippet") or item.get("code"),
        "version": item.get("version_binding") or item.get("version") or item.get("requested_version"),
    }
    return hashlib.sha256(canonical_projection_bytes(material)).hexdigest()

