def _probe(contract: NeedContract) -> dict[str, Any]:
    need = contract.need
    text = ' '.join(part for part in (need.context, need.query_span_text) if part)
    roles = query_constraint_roles(text)
    return {'query_text': text, 'query_origin': 'retrieval_need',
        'query_terms': list(documentation_query_terms(text)),
        'exact_terms': list(dict.fromkeys((*roles.hard_exact, *need.hard_exact))),
        'bound_subjects': list(roles.bound_subjects),
        'need_subject': need.subject, 'need_relation': need.relation,
        'need_context': need.context}

def qualify_evidence(
    probe: Mapping[str, Any], *, query_id: str, visible_text: str,
    evidence_text: str | None = None,
    catalog_role: str = "", forbidden_catalog_roles: tuple[str, ...] = (),
    forbidden_evidence_terms: tuple[str, ...] = (),
    candidate: Mapping[str, Any] | None = None,
    expected_project_identity: str | None = None,
    lifecycle_intent: LifecycleIntent = "current",
) -> EvidenceQualification:
    """Qualify one retrieval probe against evidence visible to the model."""
    # Body-bound decisions belong to the current bytes, never the incoming trace.
    probe = {key: value for key, value in probe.items() if key not in {
        "need_local_witness", "admission_route", "matched_need_ids",
        "need_witness_spans", "need_witness_source_key", "_admission_demands",
        "context_eligible", "context_need_ids", "_need_context",
    }}
    result = dict(probe)
    policy_reason = evidence_policy_rejection_reason(
        probe, visible_text=visible_text, catalog_role=catalog_role,
        forbidden_catalog_roles=forbidden_catalog_roles,
        forbidden_evidence_terms=forbidden_evidence_terms, candidate=candidate,
        expected_project_identity=expected_project_identity, lifecycle_intent=lifecycle_intent,
    )
    if policy_reason is not None:
        return _rejected(result, policy_reason)
    body = evidence_text if evidence_text is not None else visible_text
    from .query_reference_binding import prepare_reference_probe
    probe, reference_reason = prepare_reference_probe(probe, candidate=candidate, evidence_text=body)
    result = dict(probe)
    if reference_reason is not None:
        return _rejected(result, reference_reason)
    lines = body.splitlines()
    substantive_lines = []
    heading_lines = []
    table_rows: list[tuple[str, str]] = []
    fence = ""
    for index, line in enumerate(lines):
        fence_match = re.match(r"^ {0,3}(`{3,}|~{3,})(.*)$", line)
        if fence:
            if (
                fence_match and fence_match[1][0] == fence[0]
                and len(fence_match[1]) >= len(fence) and not fence_match[2].strip()
            ):
                fence = ""
            elif line.strip():
                substantive_lines.append(line)
            continue
        if fence_match:
            fence = fence_match[1]
            continue
        if line.lstrip().startswith("#"):
            heading_lines.append(line.lstrip().lstrip("#").strip())
            continue
        next_line = lines[index + 1].strip() if index + 1 < len(lines) else ""
        if re.fullmatch(r"[=-]{3,}", next_line):
            heading_lines.append(line.strip())
            continue
        if (
            "|" in line and re.fullmatch(
                r"\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)*\|?", next_line,
            )
        ):
            for row in lines[index + 2:]:
                if not row.strip() or "|" not in row:
                    break
                table_rows.append((line, row))
            continue
        line = _substantive_markdown_line(line)
        if line.strip(" \t-*+0123456789.)|:<>_="):
            substantive_lines.append(line)
    if not substantive_lines:
        return _rejected(result, "metadata_only_evidence")
    # A heading may identify the subject of an already relevant body, but cannot
    # turn unrelated prose or a single generic match into factual evidence.
    normalized_evidence = "\n".join(substantive_lines).casefold()
    normalized_headings = "\n".join(heading_lines).casefold()

    relation_text = str(probe.get("query_text") or "").casefold()
    comparison_relation = _comparison_relation_probe(query_id, relation_text)
    if query_id.startswith("query-relation-"):
        negated_state = re.search(
            r"(?<!\w)(?:not|without|never|no)(?!\w)\s+([a-z][a-z0-9_-]{2,})\s*$",
            relation_text, re.I,
        )
        if negated_state is not None:
            state = re.escape(negated_state.group(1))
            if re.search(
                rf"(?<!\w)(?:not|without|never|no)(?!\w)(?:\s+\w+){{0,2}}\s+{state}(?!\w)",
                normalized_evidence, re.I,
            ) is None:
                return _rejected(result, "missing_visible_relation_negation")

    if str(probe.get("mode") or "") == "exact_path":
        query_text = str(probe.get("query_text") or "").replace("\\", "/").casefold()
        normalized_visible = visible_text.replace("\\", "/").casefold()
        qualified = bool(query_text and query_text in normalized_visible)
        result.update(
            qualified=qualified,
            qualification_reason="visible_exact_path" if qualified else "missing_visible_exact_path",
        )
        return EvidenceQualification(
            qualified,
            (query_id,) if qualified else (),
            _coverage_kind(probe) if qualified else None,
            str(result["qualification_reason"]),
            result,
        )

    terms = tuple(
        str(value).casefold() for value in probe.get("query_terms") or () if value
    )
    if not terms:
        terms = tuple(dict.fromkeys(
            token.casefold()
            for token in re.findall(
                r"[A-Za-zА-Яа-яЁё0-9_.-]{4,}", str(probe.get("query_text") or ""),
            )
        ))
    if comparison_relation:
        terms = tuple(term for term in terms if term not in _COMPARISON_RELATION_MARKERS)
        relation_units = _relation_units(body)
        if not any(_visible_comparison_relation(unit, terms) for unit in relation_units):
            return _rejected(result, "missing_visible_comparison_relation")
    if not terms:
        return _rejected(result, "missing_visible_query_terms")

    exact_terms = tuple(
        str(value).casefold() for value in probe.get("exact_terms") or () if value
    )
    body_matched = tuple(
        term for term in terms
        if _visible_term_present(
            term, normalized_evidence, exact=term in exact_terms,
        )
    )
    heading_context_allowed = len(body_matched) >= 2
    bound_subjects = tuple(
        str(value).casefold() for value in probe.get("bound_subjects") or () if value
    )
    bound_subject_context = str(probe.get("bound_subject_context") or "").casefold()
    missing_bound_subjects = tuple(
        subject for subject in bound_subjects
        if not _visible_term_present(subject, normalized_evidence, exact=True)
        and not (
            heading_context_allowed
            and _visible_term_present(subject, bound_subject_context, exact=True)
        )
    )
    if missing_bound_subjects:
        result.update(
            bound_subjects=list(bound_subjects),
            missing_bound_subjects=list(missing_bound_subjects),
            qualified=False,
            qualification_reason="missing_bound_subject",
        )
        return EvidenceQualification(
            False, (), None, "missing_bound_subject", result,
        )
    # Column labels describe a substantive row, not standalone evidence. Only
    # bind them when that table's key cell contains every requested exact term.
    # They may recover a relation term, but never supply a missing identifier.
    table_context = _bound_table_context(table_rows, exact_terms)
    table_matched = tuple(
        term for term in terms if term not in exact_terms
        and _visible_term_present(term, table_context, exact=False)
    )
    matched = tuple(dict.fromkeys((
        *body_matched,
        *table_matched,
        *(
            term for term in terms
            if heading_context_allowed
            and (_visible_term_present(term, normalized_headings, exact=term in exact_terms)
                 or (term in bound_subjects and _visible_term_present(term, bound_subject_context, exact=True)))
        ),
    )))
    exact_evidence = (
        f"{normalized_evidence}\n{normalized_headings}"
        if heading_context_allowed else normalized_evidence
    )
    missing_exact = tuple(
        term for term in exact_terms
        if not _visible_term_present(term, exact_evidence, exact=True)
    )
    missing_parent_exact = tuple(
        str(value).casefold()
        for value in probe.get("parent_exact_terms") or ()
        if not _visible_term_present(str(value).casefold(), exact_evidence, exact=True)
    )
    ratio = len(matched) / len(terms)
    required_ratio = (
        1.0 if len(terms) == 1
        else 0.4 if exact_terms or comparison_relation
        else 0.5
    )
    qualified = bool(matched) and ratio >= required_ratio and not missing_exact
    reason = "visible_fields" if qualified else "insufficient_visible_match"
    result.update({
        "matched_terms": list(matched),
        "body_matched_terms": list(body_matched),
        "heading_context_used": heading_context_allowed and any(
            term not in body_matched and term not in table_matched for term in matched
        ),
        "table_context_used": any(term not in body_matched for term in table_matched),
        "missing_exact_terms": list(missing_exact),
        "missing_parent_exact_terms": list(missing_parent_exact),
        "matched_term_count": len(matched),
        "match_ratio": round(ratio, 4),
        "qualified": qualified,
        "qualification_reason": reason,
    })
    from .admission_contract import choose_need_admission
    decision, witness = choose_need_admission(
        probe, query_id=query_id, text=body,
        legacy_qualified=qualified, missing_exact=missing_exact,
    )
    qualified = decision.admitted
    # Preserve old reason text on unsupported legacy forms.
    if decision.route != "legacy_strict":
        reason = decision.reason
    if witness.status != "unknown" or probe.get("query_origin") == "retrieval_need":
        result.update(qualified=qualified, qualification_reason=reason,
            admission_route=decision.route, matched_need_ids=list(decision.matched_need_ids))
    if decision.route == "typed_local":
        result.update(need_local_witness=True,
            need_witness_spans=[list(span) for span in witness.spans],
            need_witness_source_key=witness.source_key)
    return EvidenceQualification(
        qualified,
        (query_id,) if qualified else (),
        _coverage_kind(probe) if qualified else None,
        reason,
        result,
    )

def _applicable_context(contract: NeedContract, question: str, body: str) -> bool:
    """Unknown conditions do not become permissions from similar words."""
    if not contract.constraint_spans:
        return True
    frame = parse_admission_frame(contract.need.query_span_text)
    constraints = {slot.role: slot for slot in frame.constraints} if frame else {}
    if {'condition_subject', 'condition_state'} <= constraints.keys():
        # Require the actual local prefix, not a state somewhere else on a page.
        required_entity = constraints['condition_subject'].text
        required_state = constraints['condition_state'].canonical
        for block in re.split(r'\n\s*\n', body):
            match = _PREFIX_CONDITION.match(' '.join(block.split()))
            if (match and re.fullmatch(_phrase(required_entity), match['entity'], re.I)
                    and _STATES.get(match['state'].casefold()) == required_state):
                remainder = ' '.join(block.split())[match.end():]
                clause = re.split(r'(?<=[.!?])\s+|;\s*', remainder, maxsplit=1)[0]
                subject = contract.need.subject
                if subject and re.search(technical_term_pattern(subject, exact=True), clause, re.I):
                    return True
        return False
    # The composed precedence form asks about conflicting sources, not a state
    # of a named feature. It can receive topic context but is not proven here.
    if contract.need.relation == 'precedence':
        text = ' '.join(question[s.start:s.end] for s in contract.constraint_spans)
        return bool(re.search(r'\bdefine\s+different\b', text, re.I)
                    and not re.search(r'\b(?:not|only|unless|except|without)\b', text, re.I))
    return False

def validate_evidence_set(bundle: EvidenceSet, contracts, prepared_sources: Mapping):
    """Recompute every dependency from current prepared bytes, not cached flags.

    This function certifies source/structure integrity only. proposed_need_ids
    are routing hints and never a claim that those needs are supported.
    """
    reasons=[];members=bundle.member_spans
    if not members or len(members)>8 or len(bundle.edges)>64:
        return ('dependency_budget_exceeded',)
    keys={ref.source for ref in members}
    if len(keys)!=1:return ('mixed_source_scope',)
    key=next(iter(keys));record=prepared_sources.get(key)
    if not isinstance(record,Mapping):return ('source_not_prepared',)
    identity=record.get('source') or {}
    expected={'scope':asdict(key.scope),'document_id':key.document_id,
        'canonical_path':key.canonical_path,'content_sha256':key.document_sha256}
    if any(identity.get(k)!=v for k,v in expected.items()):
        return ('source_identity_mismatch',)
    raw=record.get('raw_document')
    if not isinstance(raw,str) or any(not span_matches_source(ref,raw) for ref in members):
        return ('source_span_mismatch',)
    graph=source_graph(raw,key);current=set(graph.edges);visible=set(members)
    if not visible<={ref for _,ref in graph.nodes}:reasons.append('unrecognized_source_unit')
    for edge in bundle.edges:
        if edge.parent not in visible or edge.child not in visible:
            reasons.append('missing_dependency_endpoint')
        if edge not in current:reasons.append('unverified_dependency_edge')
    for edge in current:
        if edge.child in visible and edge.parent not in visible:
            reasons.append('missing_dependency_endpoint')
        elif edge.child in visible and edge.parent in visible and edge not in bundle.edges:
            reasons.append('missing_dependency_edge')
    for intro,children in graph.lists:
        if visible.intersection(children) and not set((intro,*children))<=visible:
            reasons.append('incomplete_list_dependency')
    if _depth_error(visible,bundle.edges,2):reasons.append('dependency_budget_exceeded')
    known={c.need.need_id for c in contracts}
    if not set(bundle.proposed_need_ids)<=known:reasons.append('unknown_proposed_need')
    if bundle.set_id!=_set_id(_ordered(members),bundle.edges):reasons.append('set_identity_mismatch')
    return tuple(dict.fromkeys(reasons))

def _witness_is_visible(spans, bundle: EvidenceSet, offset: int, raw: str) -> bool:
    """Do not borrow a matched clause outside the proposed original members."""
    members = sorted((ref.start, ref.end) for ref in bundle.member_spans)
    for a, b in spans:
        left, end = offset + a, offset + b
        for start, stop in members:
            if stop <= left or start >= end:
                continue
            if start > left and raw[left:start].strip('\r\n'):
                return False
            left = max(left, min(stop, end))
        if left < end and raw[left:end].strip('\r\n'):
            return False
    return bool(spans)

def iter_need_context_variants(
    candidates, *, query_plan: dict[str, Any], expected_project_identity: str | None,
    max_tokens: int, diagnostics: dict[str, Any],
):
    """Yield freshly checked original-byte alternatives, without selecting one."""
    question = str(query_plan.get('original_question') or '')
    if not question or not expected_project_identity:
        return None
    public_ids = tuple(query_plan.get('public_query_ids') or query_plan.get('query_ids') or ())
    outcomes = diagnostics.setdefault('need_context_fallback', [])
    for original in candidates[:24]:
        if not isinstance(original, Mapping) or original.get('source_class') != 'project_doc':
            continue
        if evidence_policy_rejection_reason({}, visible_text='', candidate=original,
                expected_project_identity=expected_project_identity,
                lifecycle_intent=original.get('_lifecycle_intent', 'current')) is not None:
            continue
        root = original.get('_reference_root_plan')
        evidence = original.get('_reference_evidence')
        if not isinstance(root, Mapping) or not isinstance(evidence, Mapping):
            continue
        plan = _current_plan(root, question)
        if plan is None or plan.scope.project_id != expected_project_identity:
            continue
        identity = evidence.get('source') or {}
        raw_document = evidence.get('raw_document')
        raw = evidence.get('text')
        start, end = evidence.get('char_start'), evidence.get('char_end')
        if (not isinstance(raw_document, str) or not isinstance(raw, str)
                or type(start) is not int or type(end) is not int
                or not 0 <= start < end <= len(raw_document) or raw_document[start:end] != raw):
            continue
        key = SourceKey(plan.scope, str(identity.get('document_id') or ''),
            str(identity.get('canonical_path') or ''), str(identity.get('content_sha256') or ''))
        bundles = _current_bundles(original.get('_evidence_sets'), key)
        if bundles is None:
            continue
        records = {key: {'source': identity, 'raw_document': raw_document}}
        contracts = compile_need_contracts(question, plan)
        # Use existing finite window/block alternatives, not full-parent rescue.
        ranges = {(a, b) for a, b in source_block_alternatives(raw).spans if b - a <= 640}
        if any(c.requirement in {'set', 'set_with_explanations'} for c in contracts):
            # Whole introduced lists are finite source structures, not parents.
            # Their real DTO cost, not a character cap, decides delivery.
            for intro, items in source_graph(raw_document, key).lists:
                left, right = intro.start, max((s.end for s in items), default=intro.end)
                if start <= left < right <= end and len(items) <= 8:
                    ranges.add((left - start, right - start))
        for limit in _projection_limits(raw):
            _, a, b = _focused_snippet(raw, (question,), limit=limit)
            if b - a <= 640:
                ranges.add((a, b))
        ranges = sorted(ranges, key=lambda s: (
            not _is_complete_source_span(raw, raw[s[0]:s[1]], span_start=s[0]),
            -(s[1] - s[0]), s[0]))[:16]
        for a, b in ranges:
            snippet = raw[a:b]
            if not snippet.strip():
                continue
            normalized = _docs_source(dict(original), display_snippet=snippet)
            if normalized is None:
                continue
            normalized['line_start'], normalized['line_end'] = _focused_line_range(
                raw, a, b, original.get('line_start'))
            normalized.update(project_identity=expected_project_identity,
                authority=str(original.get('authority') or 'supporting'),
                scope=str(original.get('doc_scope') or 'project'))
            candidate = {**original, **normalized, 'char_span': [start + a, start + b],
                'char_start': start + a, 'char_end': start + b, 'snippet': snippet}
            dispositions = tuple(classify_need_context(contract, reference_plan=plan,
                candidate=candidate, bundles=bundles, prepared_sources=records)
                for contract in contracts[:12])
            permitted = tuple(row for row in dispositions if row.state != 'blocked')
            if len(outcomes) < 32:
                outcomes.append({'candidate_id': str(normalized.get('evidence_id') or ''),
                    'span': [start + a, start + b], 'dispositions': [asdict(row) for row in dispositions]})
            if not permitted:
                continue
            # No qualified/root/host attribution is manufactured for this row.
            normalized['retrieval_query_matches'] = {}
            normalized['retrieval_query_ids'] = []
            decision = context_selection_decision([normalized], public_ids)
            payload = _payload([normalized], decision=decision, query_plan=query_plan)
            if docs_context_budget_tokens(payload) > max_tokens:
                continue
            yield dict(original), normalized, contracts, permitted

def _current_plan(root: Mapping[str, Any], question: str) -> ReferencePlan | None:
    if root.get('question') != question:
        return None
    try:
        scope = ScopeKey(**root['scope'])
        references = tuple(ResolvedReference(QueryMention(**row['mention']),
            row['role'], row['state'], tuple(row['source_ids']), row['reason'])
            for row in root['references'])
        return ReferencePlan(question, references, scope, root['catalog_complete'])
    except (KeyError, TypeError, ValueError):
        return None

def documentation_query_terms(question: str) -> tuple[str, ...]:
    """Bounded lexical probe terms, excluding standalone request connectors."""
    # A leading enumeration imperative describes answer presentation, not a
    # fact that documentation must repeat. Keep the public question, interior
    # occurrences, exact identities and all condition words unchanged.
    lexical_question = re.sub(
        r"^\s*(?:перечисли(?:те)?|enumerate)\s+(?=\S)", "", question, count=1, flags=re.I,
    )
    return tuple(dict.fromkeys(
        token.casefold()
        for token in re.findall(r"[A-Za-zА-Яа-яЁё0-9_.:/+-]+", lexical_question)
        if token.casefold() not in _REQUEST_FRAMING_TERMS
        and (len(token) >= 4 or is_exact_technical_token(token))
    ))[:32]

def source_graph(raw: str, source: SourceKey) -> DependencyGraph:
    """Cache only immutable parse inputs/edges; never query acceptance decisions."""
    if digest(raw)!=source.document_sha256:
        return DependencyGraph((),(),())
    nodes=[];edges=[];lists=[]
    for parent in parse_markdown_parents(raw, source.document_id):
        atoms=_atom_spans(raw,parent.char_start,parent.char_end)
        local=[];heading=None;previous=None
        for atom in atoms:
            ref=source_span(source,raw,atom.start,atom.end)
            if ref.start>=ref.end or atom.atom_type=='whitespace':
                continue
            if atom.atom_type=='heading':
                first_line=raw.find('\n',atom.start,atom.end)
                heading=source_span(source,raw,atom.start,first_line if first_line>=0 else atom.end)
                local.append(('heading',heading));previous=None
                continue
            parts=(_list_parts(raw,source,atom.start,atom.end) if atom.atom_type=='list'
                   else _table_parts(raw,source,atom.start,atom.end) if atom.atom_type=='table' else None)
            if parts:
                intro,children=parts;kind=atom.atom_type
                local.append((kind+'_intro',intro));local.extend((kind+'_item',c) for c in children)
                rule='introduced-list-item-v1' if kind=='list' else 'markdown-table-row-v1'
                edges.extend(DependencyEdge(kind,intro,child,rule) for child in children)
                if kind=='list':lists.append((intro,children))
                previous=None
                continue
            local.append((atom.atom_type,ref))
            if atom.atom_type=='prose':
                if previous:
                    subject=_single_subject(raw[previous.start:previous.end])
                    child_text=raw[ref.start:ref.end].strip()
                    if subject:
                        name,verb=subject
                        if verb in {'is','means','denotes','refers'} and re.match(re.escape(name)+r'\s+\w',child_text):
                            edges.append(DependencyEdge('definition',previous,ref,'named-definition-reference-v1'))
                        if _ANAPHORA.match(child_text):
                            edges.append(DependencyEdge('anaphora',previous,ref,'single-subject-anaphora-v1'))
                        if _CAUSE.match(child_text):
                            edges.append(DependencyEdge('cause',previous,ref,'single-subject-cause-v1'))
                previous=ref
            else:
                previous=None
        if heading:
            edges.extend(DependencyEdge('heading',heading,ref,'markdown-owning-heading-v1')
                         for kind,ref in local if kind!='heading')
        nodes.extend(local)
    return DependencyGraph(tuple(nodes),tuple(dict.fromkeys(edges)),tuple(lists))

